"""
Text extraction module optimized for Question-Centric Mapping and Multi-File Context.
Updated: March 2026 - Supports Dynamic Marks, Multi-Reference Learning, and Phase Updates.
"""
import asyncio
import os
import re
import io
import base64
from typing import Dict, List, Any, Optional, Union
from langfuse import observe, get_client
from opentelemetry import trace
client = get_client()
