class EvaluationModelExtractor:
    """Analyzes grading methodology from teacher-corrected reference papers."""

    def __init__(self):
        import boto3
        self.client = boto3.client(
            service_name='bedrock-runtime',
            region_name=os.getenv("AWS_REGION", os.getenv("AWS_DEFAULT_REGION", "us-east-1"))
        )
        self.model_name = os.getenv("BEDROCK_EXTRACTION_MODEL_ID", os.getenv("BEDROCK_TEXT_MODEL_ID", os.getenv("BEDROCK_TEXT_MODEL", "us.amazon.nova-lite-v1:0")))

    @observe(as_type="generation", name="extract_evaluation_model")
    async def extract_evaluation_model(self, reference_content: str, update_callback=None) -> Dict[str, Any]:
        """Synthesizes a unified grading model from corrected reference papers."""
        if update_callback:
            update_callback("Phase 1: Synthesizing grading style from reference papers...")

        if not reference_content or not reference_content.strip():
            return self._default_evaluation_model()

        prompt = f"""
        TASK: Analyze these CORRECTED REFERENCE PAPERS to synthesize the EXACT teacher's grading methodology.
        The reference papers are the ABSOLUTE GOLD STANDARD for what constitutes correct answers.

        {reference_content}

        ANALYZE AND EXTRACT:
        1. FULL_MARKS_CRITERIA: What EXACT content triggers a perfect score? (Use actual examples from reference papers)
        2. PARTIAL_MARKS_RULES: When does the teacher deduct marks? For what specific reasons? (Find real examples)
        3. GRAMMAR_TOLERANCE: Does the teacher penalize poor handwriting/grammar? (Check the reference papers)
        4. KEYWORD_VS_CONCEPT: Does the teacher require exact keywords, or is conceptual understanding enough?
        5. MINIMUM_FOR_PASSING: What is the absolute minimum content for any marks at all?
        6. STRICTNESS_LEVEL: Based on the actual corrected papers: 'Liberal', 'Moderate', or 'Strict'?

        CRITICAL INSTRUCTION:
        If the teacher gave FULL MARKS (e.g., Q1: 5/5) for a 2-line conceptual answer in the reference paper,
        then ANY student who provides similar conceptual content must ALSO receive full marks.
        The reference paper's scoring is the LAW. Do not deviate from it.

        Return in structured format:
        STRICTNESS: [Level]
        GRAMMAR_TOLERANCE: [High/Medium/Low]
        REFERENCE_EXAMPLES: [Key findings from actual papers]
        RULES: [Consolidated Rules derived from actual marking]
        CONFIDENCE: [0.0-1.0]
        """        
        if trace.get_current_span().is_recording():
            client.update_current_generation(
                model=self.model_name,
                input=prompt
            )
        try:
            response = self.client.converse(
                modelId=self.model_name,
                messages=[{"role": "user", "content": [{"text": prompt}]}],
                inferenceConfig={
                    "temperature": 0.1
                }
            )
            text = response['output']['message']['content'][0]['text']
            if trace.get_current_span().is_recording():
                usage = response.get("usage", {})
                client.update_current_generation(
                    output=text,
                    usage_details={
                        "input": usage.get("inputTokens", 0),
                        "output": usage.get("outputTokens", 0)
                    }
                )
            return self._parse_evaluation_criteria(text)
        except Exception as e:
            print(f"[ERROR] Reference analysis failed: {e}")
            if trace.get_current_span().is_recording():
                client.update_current_generation(
                    level="ERROR",
                    status_message=str(e)
                )
            return self._default_evaluation_model()

    def _parse_evaluation_criteria(self, text: str) -> Dict[str, Any]:
        raw_confidence = self._extract_field(text, "CONFIDENCE", "0.8")
        clean_confidence = re.sub(r"[^\d.]", "", raw_confidence)

        try:
            if clean_confidence and clean_confidence != ".":
                confidence_value = float(clean_confidence)
            else:
                confidence_value = 0.8
        except ValueError:
            confidence_value = 0.8

        return {
            "strictness_level": self._extract_field(text, "STRICTNESS", "Moderate"),
            "grammar_tolerance": self._extract_field(text, "GRAMMAR_TOLERANCE", "High"),
            "reference_examples": self._extract_field(text, "REFERENCE_EXAMPLES", ""),
            "rules": self._extract_field(text, "RULES"),
            "extraction_confidence": confidence_value,
            "source": "multi_reference_analysis"
        }

    def _extract_field(self, text: str, field_name: str, default: str = "") -> str:
        pattern = rf"{field_name}:\s*(.*?)(?=\n[A-Z_]+:|$)"
        match = re.search(pattern, text, re.IGNORECASE | re.DOTALL)
        return match.group(1).strip() if match else default

    def _default_evaluation_model(self) -> Dict[str, Any]:
        return {"strictness_level": "Moderate", "rules": "Use standard marking.", "source": "default"}

class DocumentExtractor:
    """Handles OCR and Dynamic Mark extraction from PDFs/Images."""

    def __init__(self):
        import boto3
        self.client = boto3.client(
            service_name='bedrock-runtime',
            region_name=os.getenv("AWS_REGION", os.getenv("AWS_DEFAULT_REGION", "us-east-1"))
        )
        self.model_name = os.getenv("BEDROCK_VISION_MODEL_ID", os.getenv("BEDROCK_TEXT_MODEL", "us.amazon.nova-lite-v1:0"))
        self.secondary_model_name = os.getenv("BEDROCK_SECONDARY_VISION_MODEL_ID", "us.amazon.nova-pro-v1:0")

    def _preprocess_image(self, image: Image.Image) -> bytes:
        """Converts PIL Image directly to raw JPEG bytes for Bedrock."""
        if image.mode != 'RGB': 
            image = image.convert('RGB')
        buffered = io.BytesIO()
        image.save(buffered, format="JPEG", quality=95)
        return buffered.getvalue()

    @observe(as_type="generation", name="transcribe_page")
    async def transcribe_page(self, image: Image.Image, page_no: int, source: str, update_callback=None) -> Dict[str, Any]:
        image_bytes = self._preprocess_image(image)

        prompts = {
            "teacher": "MASTER ANSWER KEY. Extract each Question Number and its explicitly assigned Max Marks. You MUST ONLY extract marks that are located in a distinct, structured 'column of marks' or a clear tabular format mapping questions to marks. Completely IGNORE any inline marks embedded within paragraphs or text (e.g., ignore '...with examples. (4 Marks)'). Do not infer from section headers.",
            "reference": "CORRECTED PAPER. Extract the student's answer and the marks given by the teacher.",
            "student": "STUDENT SCRIPT. Transcribe the handwriting exactly as written."
        }

        prompt = f"""
        TASK: {prompts.get(source, 'Transcribe document.')}
        1. Locate Question Numbers (Q1, Q2, 1, 2 etc.).
        2. Identify Marks/Scores EXPLICITLY associated with each individual question. STRICT RULE: ONLY extract marks if they appear in a dedicated 'marks column' or a clear tabular list mapping question numbers to marks. Do NOT extract inline marks from textual descriptions (e.g., ignore '(4 Marks)' inside a paragraph). If a question does not have a mark in the column, do not include it.
        3. Identify Metadata: Student Name and Roll Number.
        4. Calculate OCR Confidence for this page as a floating-point score between 0.0 and 1.0 based on visibility, legibility, and completeness.
        5. Transcribe all text under CONTENT.

        OUTPUT FORMAT:
        NAME: [Value]
        ROLL: [Value]
        QUESTION_MARKS: [Q1: 5, Q2: 10]
        OCR_CONFIDENCE: [0.0-1.0]
        CONTENT: [Full Text]
        """

        messages = [
            {
                "role": "user",
                "content": [
                    {
                        "image": {
                            "format": "jpeg",
                            "source": {
                                "bytes": image_bytes
                            }
                        }
                    },
                    {
                        "text": prompt
                    }
                ]
            }
        ]

        if trace.get_current_span().is_recording():
            client.update_current_generation(
                model=self.model_name,
                input={
                    "page_no": page_no,
                    "source": source,
                    "prompt": prompt
                }
            )
        try:
            response = self.client.converse(
                modelId=self.model_name,
                messages=messages,
                inferenceConfig={
                    "maxTokens": 800
                }
            )
            raw_text = response['output']['message']['content'][0]['text']
            if trace.get_current_span().is_recording():
                usage = response.get("usage", {})
                client.update_current_generation(
                    output=raw_text,
                    usage_details={
                        "input": usage.get("inputTokens", 0),
                        "output": usage.get("outputTokens", 0)
                    }
                )
        except Exception as e:
            if trace.get_current_span().is_recording():
                client.update_current_generation(
                    level="ERROR",
                    status_message=f"Primary OCR failed: {str(e)}"
                )
            raise e

        # ISOLATE QUESTION MARKS SECTION
        header_section = raw_text.split("CONTENT:")[0] if "CONTENT:" in raw_text else raw_text

        # Parse confidence score
        ocr_conf_match = re.search(r"OCR_CONFIDENCE:\s*([\d.]+)", header_section)
        ocr_confidence = 0.95  # Default high confidence
        if ocr_conf_match:
            try:
                ocr_confidence = float(ocr_conf_match.group(1))
                if ocr_confidence > 1.0:
                    ocr_confidence = ocr_confidence / 100.0
            except ValueError:
                pass

        # Trigger Secondary AI OCR if confidence is between 65% and 70%
        used_secondary = False
        if 0.65 <= ocr_confidence <= 0.70:
            used_secondary = True
            msg = f"Page {page_no}: OCR confidence is {ocr_confidence:.1%}. Triggering Secondary AI OCR (Amazon Nova Pro) for precise extraction..."
            if update_callback:
                update_callback(msg)
            print(f"[OCR CONFIDENCE ROUTING] {msg}")

            try:
                if trace.get_current_span().is_recording():
                    client.update_current_generation(
                        model=self.secondary_model_name,
                        metadata={
                            "secondary_ocr_triggered": True,
                            "primary_ocr_confidence": ocr_confidence
                        }
                    )
                response = self.client.converse(
                    modelId=self.secondary_model_name,
                    messages=messages,
                    inferenceConfig={
                        "maxTokens": 800
                    }
                )
                raw_text = response['output']['message']['content'][0]['text']
                if trace.get_current_span().is_recording():
                    usage = response.get("usage", {})
                    client.update_current_generation(
                        output=raw_text,
                        usage_details={
                            "input": usage.get("inputTokens", 0),
                            "output": usage.get("outputTokens", 0)
                        }
                    )
                header_section = raw_text.split("CONTENT:")[0] if "CONTENT:" in raw_text else raw_text

                ocr_conf_match = re.search(r"OCR_CONFIDENCE:\s*([\d.]+)", header_section)
                if ocr_conf_match:
                    try:
                        new_conf = float(ocr_conf_match.group(1))
                        ocr_confidence = new_conf / 100.0 if new_conf > 1.0 else new_conf
                    except ValueError:
                        ocr_confidence = 0.92
                else:
                    ocr_confidence = 0.92
            except Exception as e:
                print(f"[WARNING] Secondary AI OCR failed: {e}. Falling back to primary transcription.")

        ocr_needs_review = ocr_confidence < 0.65
        if ocr_needs_review:
            msg = f"Page {page_no}: OCR confidence is {ocr_confidence:.1%}. Flags Teacher Review."
            if update_callback:
                update_callback(msg)
            print(f"[OCR CONFIDENCE ROUTING] {msg}")

        qm_match = re.search(r"QUESTION_MARKS:\s*\[?(.*?)\]?(?=\n[A-Z_]+:|\Z)", header_section, re.IGNORECASE | re.DOTALL)
        question_marks_text = qm_match.group(1) if qm_match else header_section

        marks_matches = re.findall(r"(?:Q|Question|q)?\s*(\d+)[\s.:-]*([\.\d.]+)", question_marks_text)

        q_marks = {}
        for q, m in marks_matches:
            if re.search(r'\d', m):
                try:
                    q_marks[f"Q{q}"] = float(m)
                except ValueError:
                    continue

        content = raw_text.split("CONTENT:")[1].strip() if "CONTENT:" in raw_text else raw_text
        name_match = re.search(r"NAME:\s*(.*)", raw_text)
        roll_match = re.search(r"ROLL:\s*(.*)", raw_text)

        return {
            "page_no": page_no,
            "content": content,
            "student_name": name_match.group(1).strip() if name_match else "Unknown",
            "roll_no": roll_match.group(1).strip() if roll_match else "Unknown",
            "question_marks_found": q_marks,
            "ocr_confidence": ocr_confidence,
            "ocr_needs_review": ocr_needs_review,
            "used_secondary_ocr": used_secondary
        }

    async def extract_from_file(self, file_path: str, source: str, update_callback=None) -> Dict[str, Any]:
        file_ext = Path(file_path).suffix.lower()
        images = convert_from_path(file_path, dpi=200) if file_ext == '.pdf' else [Image.open(file_path)]

        pages_content = []
        for i, img in enumerate(images):
            if update_callback:
                update_callback(f"Processing {source} page {i+1} of {len(images)}...")

            result = await self.transcribe_page(img, i+1, source, update_callback)

            try:
                base_name = Path(file_path).stem
                page_dir = Path("temp_uploads") / "pages"
                page_dir.mkdir(parents=True, exist_ok=True)
                page_img_path = page_dir / f"{source}_{base_name}_page_{i+1}.png"
                img.save(page_img_path, format="PNG")
                result["image_path"] = str(page_img_path)
            except Exception as e:
                print(f"[WARNING] Could not save page image: {e}")
                result["image_path"] = None

            pages_content.append(result)

        all_q_marks = {}
        for p in pages_content:
            all_q_marks.update(p.get("question_marks_found", {}))

        ocr_needs_review = any(p.get("ocr_needs_review", False) for p in pages_content)

        return {
            "source": source, 
            "pages": pages_content, 
            "question_marks": all_q_marks,
            "total_marks_possible": sum(all_q_marks.values()),
            "ocr_needs_review": ocr_needs_review
        }

@observe(name="extract_documents")
async def extract_documents(
    teacher_path: str, 
    student_path: str, 
    reference_paths: Optional[List[str]] = None, 
    confidence_threshold: float = 0.0, 
    update_callback=None
):
    """Orchestrator for the entire extraction phase with UI feedback."""
    doc_extractor = DocumentExtractor()
    eval_extractor = EvaluationModelExtractor()

    # 1. Multi-Reference Paper Analysis
    combined_ref_text = ""
    eval_model = None
    if reference_paths:
        # Normalize reference paths if passed as string instead of list
        if isinstance(reference_paths, str):
            reference_paths = [reference_paths]

        for i, path in enumerate(reference_paths):
            if update_callback:
                update_callback(f"Phase 1: Analyzing Reference Paper {i+1} of {len(reference_paths)}...")
            ref_data = await doc_extractor.extract_from_file(path, "reference")
            combined_ref_text += "\n" + "\n".join([p['content'] for p in ref_data['pages']])

        eval_model = await eval_extractor.extract_evaluation_model(combined_ref_text, update_callback)

    # 2. Teacher Key Extraction
    if update_callback: update_callback("Phase 2: Extracting Marks from Teacher Key...")
    t_data = await doc_extractor.extract_from_file(teacher_path, "teacher", update_callback)

    # 3. Student Script Transcription
    if update_callback: update_callback("Phase 3: Transcribing Student Script...")
    s_data = await doc_extractor.extract_from_file(student_path, "student", update_callback)

    # Identify metadata from the first page of the student script
    student_meta = s_data["pages"][0] if s_data["pages"] else {}

    ocr_needs_review = s_data.get("ocr_needs_review", False) or t_data.get("ocr_needs_review", False)

    return {
        "teacher_key": t_data,
        "student_script": s_data,
        "teacher_key_marks": t_data["question_marks"],
        "evaluation_model": eval_model or eval_extractor._default_evaluation_model(),
        "student_name": student_meta.get("student_name", "Unknown"),
        "roll_no": student_meta.get("roll_no", "Unknown"),
        "ocr_needs_review": ocr_needs_review
    }

