import React, { useState, useRef } from 'react';
import {
  FileText,
  Upload,
  Play,
  LogOut,
  Settings,
  ChevronDown,
  CheckCircle2,
  AlertCircle,
  TrendingUp,
  ListChecks,
  Eye,
  EyeOff,
  Loader2,
  X,
  Users,
  Key,
  ShieldAlert
} from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { EvaluationResult, FileData } from './types';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('admin');
  const [password, setPassword] = useState('admin');
  const [showPassword, setShowPassword] = useState(false);
  const [teacherKey, setTeacherKey] = useState<FileData | null>(null);
  const [studentScript, setStudentScript] = useState<FileData | null>(null);
  const [referenceFile, setReferenceFile] = useState<FileData | null>(null);
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [result, setResult] = useState<EvaluationResult | null>(null);
  const [subject, setSubject] = useState('Other Subject');
  const [strictness, setStrictness] = useState(0.5);
  const [processingMessage, setProcessingMessage] = useState<string | null>(null);
  const [selectedQuestion, setSelectedQuestion] = useState<any | null>(null);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [reviewPages, setReviewPages] = useState<any[]>([]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === 'admin' && password === 'admin') {
      setIsLoggedIn(true);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'teacher' | 'student' | 'reference') => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      const fileData = {
        name: file.name,
        content: content.split(',')[1] || content, // Handle base64
        type: file.type,
        originalFile: file
      };
      if (type === 'teacher') setTeacherKey(fileData);
      else if (type === 'student') setStudentScript(fileData);
      else setReferenceFile(fileData);
    };

    if (file.type.includes('image') || file.type.includes('pdf')) {
      reader.readAsDataURL(file);
    } else {
      reader.readAsText(file);
    }
  };

  const runEvaluation = async () => {
    if (!teacherKey || !studentScript) return;
    setIsEvaluating(true);
    setResult(null);
    setProcessingMessage("Initializing connection...");

    try {
      const formData = new FormData();
      formData.append('teacherKey', teacherKey.originalFile);
      formData.append('studentScript', studentScript.originalFile);
      if (referenceFile) {
        formData.append('referenceFile', referenceFile.originalFile);
      }
      formData.append('subject', subject);
      formData.append('strictness_bias', strictness.toString());

      const response = await fetch('http://localhost:8000/api/evaluate', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const errText = await response.text();
        throw new Error(`Server Error: ${errText}`);
      }

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      if (!reader) {
        throw new Error("Failed to get stream reader");
      }

      let buffer = '';
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');

        // Save the last incomplete chunk
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.trim()) {
            try {
              const data = JSON.parse(line);
              if (data.status === 'processing') {
                setProcessingMessage(data.message);
              } else if (data.status === 'completed') {
                setResult(data.result);
                setSessionId(data.result.session_id || null);
                setReviewPages(data.result.review_pages || []);
                setProcessingMessage(null);
              } else if (data.status === 'error') {
                throw new Error(data.message);
              }
            } catch (e) {
              console.error("Stream parse error:", e);
            }
          }
        }
      }
    } catch (error) {
      console.error("Evaluation failed:", error);
      // Fallback mock data
      setResult({
        totalScore: 7.0,
        maxScore: 10.0,
        accuracy: 95.0,
        grade: 'A',
        status: 'PASS',
        questionBreakdown: [
          { id: 'Q1', score: 2, maxScore: 2, feedback: 'Perfect answer.', evalConfidence: 0.98, evalReason: 'N/A', extractConfidence: 0.90, extractReason: 'Clear handwriting', questionText: 'Define keywords and identifiers.', teacherAnswer: 'Keywords cannot be used as identifiers as they are reserved words.', studentAnswer: 'Keywords are predefined words.' },
          { id: 'Q2', score: 0, maxScore: 2, feedback: 'Missing key concepts.', evalConfidence: 0.65, evalReason: 'Ambigous conceptual explanation.', extractConfidence: 0.70, extractReason: 'Difficult handwriting', questionText: 'Specify preprocessor directive use.', teacherAnswer: 'Instructs the compiler before compilation starts.', studentAnswer: 'It is used to improve code quality.' },
          { id: 'Q3', score: 2, maxScore: 2, feedback: 'Well explained.', evalConfidence: 0.9, evalReason: 'N/A', extractConfidence: 0.88, extractReason: 'Clear handwriting', questionText: 'State value returned by strcmp.', teacherAnswer: 'Returns negative value if left string is lexicographically smaller.', studentAnswer: 'Returns negative value.' },
          { id: 'Q4', score: 1, maxScore: 2, feedback: 'Partial credit for structure.', evalConfidence: 0.8, evalReason: 'Partial match.', extractConfidence: 0.95, extractReason: 'Clear handwriting', questionText: 'Initialize 2D array.', teacherAnswer: 'int arr[2][2] = {{1, 2}, {3, 4}};', studentAnswer: 'int arr[2][2] = {{1, 2}, {3, 4}};' },
          { id: 'Q5', score: 2, maxScore: 2, feedback: 'Excellent recursion definition.', evalConfidence: 0.95, evalReason: 'N/A', extractConfidence: 0.85, extractReason: 'Clear handwriting', questionText: 'Define recursion.', teacherAnswer: 'Function calling itself directly or indirectly.', studentAnswer: 'Function calling itself.' }
        ],
        improvementTips: [
          'Review Q2: Ambiguous conceptual explanation required extensive interpretation. (Lost 2.0 marks)',
          'Review Q4: Partial match on concepts. (Lost 1.0 marks)'
        ],
        detailedFeedback: 'Technical Breakdown: SCORE_EARNED: 7.0 SCORE_TOTAL: 10 ANALYSIS: Q1: 2/2. The student correctly states that "Keywords cannot be used as Identifiers" and explains why they are "predefined words" and "reserved words" in C. This matches the logical meaning of the master key. Q2: 0/2. The student\'s answer "improve the quality, reliability, readability and manage the Compilation process" does not capture the core logical meaning of a preprocessor directive, which is to instruct the compiler to process certain instructions before actual compilation starts.',
        overallReport: 'Unsatisfactory. Significant conceptual gaps found. Please review the key and retry. Final Grade: A Status: PASS Total Marks: 7.0/10.0 Mean Conceptual Accuracy: 0.0%'
      });
    } finally {
      setIsEvaluating(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 relative overflow-hidden">
        <BackgroundShapes />
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <h1 className="text-4xl font-bold text-slate-800 mb-2">Welcome Back</h1>
          <p className="text-slate-500 text-sm">Please log in to access the Academic Evaluation System</p>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="w-full max-w-md glass-container rounded-3xl p-8 shadow-2xl"
        >
          <h2 className="text-2xl font-semibold text-slate-800 mb-6">Authentication</h2>
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1 uppercase tracking-wider">Username</label>
              <input
                type="text"
