    </>
  );
}

function ReviewPageCard({ page, sessionId, onUpdateResult }: { page: any, sessionId: string | null, onUpdateResult: (r: any) => void }) {
  const [text, setText] = useState(page.ocr_text);
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (!sessionId) return;
    setIsSaving(true);
    try {
      const response = await fetch('http://localhost:8000/api/evaluate/correct', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          session_id: sessionId,
          page_number: page.page_number,
          corrected_text: text
        }),
      });

      if (!response.ok) {
        const errText = await response.text();
        throw new Error(`Failed to save correction: ${errText}`);
      }

      const updatedData = await response.json();
      onUpdateResult(updatedData);
    } catch (e) {
      console.error(e);
      alert("Error saving page correction. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="bg-white border border-slate-100 rounded-3xl p-6 shadow-sm flex flex-col lg:flex-row gap-6 text-left">
      {/* Image Panel */}
      <div className="w-full lg:w-1/2 flex flex-col">
        <div className="flex justify-between items-center mb-3">
          <span className="text-slate-800 font-extrabold text-lg">Page {page.page_number}</span>
          <span className="text-xs font-bold text-amber-500 bg-amber-50 px-2 py-0.5 rounded-md">
            OCR Confidence: {page.confidence}%
          </span>
        </div>
        <div className="border border-slate-100 rounded-2xl overflow-hidden bg-slate-50 flex items-center justify-center min-h-[300px]">
          {page.image_url ? (
            <img
              src={page.image_url}
              alt={`Student Script Page ${page.page_number}`}
              className="max-h-[450px] object-contain w-full"
            />
          ) : (
            <span className="text-slate-400 text-sm">Image not available</span>
          )}
        </div>
      </div>

      {/* Editing Panel */}
      <div className="w-full lg:w-1/2 flex flex-col justify-between">
        <div>
          <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">
            Handwritten Transcription (Edit if incorrect)
          </span>
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            className="w-full h-[280px] bg-slate-50 border border-slate-100 rounded-2xl p-4 text-slate-700 font-medium leading-relaxed text-sm focus:outline-none focus:ring-2 focus:ring-blue-400/30 focus:bg-white transition-all resize-none"
          />
        </div>

        <div className="flex gap-4 mt-6">
          <button
            onClick={handleSave}
            disabled={isSaving}
            className="flex-1 bg-emerald-500 hover:bg-emerald-600 disabled:bg-slate-200 text-white font-bold py-3.5 rounded-xl transition-all active:scale-[0.98] shadow-md shadow-emerald-100 text-sm flex items-center justify-center gap-2 cursor-pointer"
          >
            {isSaving ? (
              <>
                <Loader2 className="animate-spin" size={16} />
                <span>Saving...</span>
              </>
            ) : (
              <span>Approve OCR</span>
            )}
          </button>

          <button
            onClick={handleSave}
            disabled={isSaving}
            className="flex-1 bg-slate-800 hover:bg-slate-700 disabled:bg-slate-200 text-white font-bold py-3.5 rounded-xl transition-all active:scale-[0.98] text-sm flex items-center justify-center gap-2 cursor-pointer"
          >
            {isSaving ? (
              <>
                <Loader2 className="animate-spin" size={16} />
                <span>Re-evaluating...</span>
              </>
            ) : (
              <span>Save & Re-evaluate</span>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

